 v+=`<rect x="37" y="97" width="110" height="111" rx="13" fill="#1a232b" stroke="${s===0?'#dcac7d':'#526d84'}"/><rect x="49" y="115" width="79" height="75" rx="8" fill="#212b34" stroke="#506a80"/><path d="M60 165q5-18 10 0t10 0t10 0t10 0t10 0" fill="none" stroke="#c28b63" stroke-width="2"/>${circle(89,148,57,'url(#warmGlow)')}`;
 v+=text(91,237,yb?'Yb oven':'Rb source','#a9bbca',12,'text-anchor="middle"')+text(91,255,yb?'Heat → vapor':'Vapor / dispenser','#5f7d97',9,'text-anchor="middle"');
