 if(s>=1&&state.slower)v+=`<path d="M262 153H170" stroke="#7eb2de" stroke-width="3" opacity=".65" marker-end="url(#arrow)" class="sweep-line"/>`;
 v+=text(217,112,'SLOW / COLLIMATE',s===1?c:'#56728a',8,'text-anchor="middle" letter-spacing="1"')+text(217,186,yb?'399 nm':'780 nm','#7e95a9',9,'text-anchor="middle"');
 v+=`<circle cx="343" cy="153" r="65" fill="#131e27" stroke="${s===2||s===3?active:'#3d5162'}"/><circle cx="343" cy="153" r="49" fill="none" stroke="#2c4051"/><path d="M304 86q39-20 78 0M304 220q39 20 78 0" fill="none" stroke="${state.gradient&&s===2?'#d4a47e':'#43586a'}" stroke-width="4"/>`;
 if(s>=2){const beam=s===3&&yb?'#a8d484':'#7eb2de';if(s!==3||state.cooling){v+=`<path d="m296 105 94 96m-94 0 94-96M343 82v142" stroke="${beam}" stroke-width="8" opacity=".12"/><path d="m296 105 94 96m-94 0 94-96" stroke="${beam}" stroke-width="1" opacity=".6"/>`;}
 v+=circle(343,153,63,'url(#coldGlow)');const spread=(s===2&&!state.gradient||s===3&&!state.cooling)?51:s>=3?15:28;
 for(let i=0;i<30;i++){const a=i*2.399,r=Math.sqrt((i+.5)/30)*spread;v+=circle(343+Math.cos(a)*r,153+Math.sin(a)*r,s>=3?2.1:1.6,c,(s===3&&!state.cooling)?'class="shake"':'');}}
 v+=text(343,251,s===3?'FURTHER COOLING':'MOT CAPTURE',s===2||s===3?c:'#7590a8',10,'text-anchor="middle"')+text(343,269,s===3?(yb?'556 nm narrow line':'Sub-Doppler molasses'):'Light + magnetic gradient','#61809a',9,'text-anchor="middle"');
 if(state.route==='reservoir'){v+=`<rect x="478" y="116" width="116" height="74" rx="12" fill="#18242e" stroke="${s===4?active:'#415567'}"/><path d="M487 143h98m-98 19h98" stroke="#435d73" stroke-dasharray="2 6"/>`;if(s>=4)for(let i=0;i<26;i++){const a=i*2.399,r=Math.sqrt((i+.5)/26);v+=circle(536+Math.cos(a)*r*43,153+Math.sin(a)*r*25,1.8,c);}v+=text(536,237,'COLD RESERVOIR',s===4?c:'#7590a8',9,'text-anchor="middle"')+text(536,255,'Optional atom supply','#5f7e98',9,'text-anchor="middle"');}
 else v+=`<path d="M421 153q88-85 204 0" fill="none" stroke="#61819c" stroke-dasharray="4 5" marker-end="url(#arrow)"/>${text(528,110,'DIRECT LOADING','#86a0b6',9,'text-anchor="middle"')}${text(536,237,'NO SEPARATE RESERVOIR','#7590a8',8,'text-anchor="middle"')}`;
