 const pos=[91,215,343,343,536,701][s];v+=`<path d="M${pos-4} 54l4 6 4-6" fill="none" stroke="#b8d5ed"/>`+text(pos,41,`0${s+1} / ${['RELEASE','SLOW','CAPTURE','COOL','STORE','ARRANGE'][s]}`,'#a9c2d8',9,'text-anchor="middle" letter-spacing="1.3"');
