function supply(){const yb=state.species==='Yb',sp=species[state.species],s=state.stage;
 const stages=[
 ['Release the atoms',yb?'Heating a Yb oven releases neutral atoms as a thermal beam into vacuum. Their motion must be reduced before loading the final tweezers.':'Rb can be supplied as vapor from a heated dispenser. A beam-source oven is another option.','What changes','The source releases atoms into vacuum. Qubit preparation follows trapping and cooling.',['Thermal motion','Vacuum']],
 ['Slow the motion',yb?'A 399 nm slowing beam and a 2D MOT can reduce and collimate the incoming motion. A Zeeman slower is an alternative design.':'780 nm light can slow and collimate Rb before capture. Some vapor-cell MOTs instead capture the slow tail of the vapor directly.','Photon momentum','Atoms preferentially absorb photons opposing their motion. Repeated scattering reduces their velocity.',['Photon momentum',yb?'399 nm':'780 nm']],
 ['Capture a cold cloud','Opposing laser beams slow atoms. A magnetic-field gradient makes the light force depend on position, producing a restoring force toward the center.','A cloud, not an array','The MOT collects many atoms in one region. It does not assign one atom to each computational site.',['Cooling + restoring force','MOT']],
 ['Reduce atomic motion',yb?'Yb commonly uses the narrower 556 nm transition for a colder MOT after initial 399 nm cooling. The two wavelengths address different atomic transitions.':'After MOT capture, polarization-gradient cooling or optical molasses can reduce Rb motion further. The MOT gradient is usually changed or switched off for this step.','Motion and internal state','Cooling reduces random motion. Optical pumping later prepares a chosen internal qubit state.',['Motional preparation',yb?'556 nm narrow line':'Sub-Doppler cooling']],
 ['Keep atoms in reserve','A cold cloud or trapped reservoir can feed later loading cycles. Some architectures instead load tweezers directly from the MOT.','Reservoir ≠ quantum memory','A fresh atom replaces a lost carrier. Error correction is needed to recover protected information after a loss.',['Optional architecture','Atom replenishment']],
 ['Assemble the array','Load individual optical tweezers, image which are occupied, then move traps to fill gaps. Further cooling and optical pumping prepare atoms for computation.','Position is not the bit','Moving a trap changes where an atom sits. Preparing |0⟩ changes its internal state. These are separate controls.',['Single-atom traps','Image → rearrange']]
 ];const t=stages[s];let control='';
 if(s===0)control=`<label class="control-label" for="flux">Illustrated source flux<output>${['','Low','Medium','High'][state.flux]}</output></label><input id="flux" class="range" type="range" min="1" max="3" step="1" value="${state.flux}"><div class="range-ends"><span>Fewer atoms</span><span>More atoms</span></div><p class="help">Adjusts the number of illustrated atoms; it does not predict a loading rate.</p>`;
 if(s===1)control=`<div class="switch-row"><label for="slower">Opposing slowing light</label>${switchButton('slower','Opposing slowing light',state.slower)}</div><p class="help">${state.slower?'The beam pushes against the incoming atoms.':'With this slowing stage off, fast incoming atoms are harder to capture. A vapor MOT may still capture an already-slow fraction.'}</p>`;
 if(s===2)control=`<div class="switch-row"><span>Magnetic-field gradient</span>${switchButton('gradient','MOT magnetic-field gradient',state.gradient)}</div><p class="help">${state.gradient?'On: position-dependent restoring force keeps the cloud centered.':'Off: the MOT restoring force is gone. Molasses can still slow atoms, but does not provide MOT confinement.'}</p>`;
 if(s===3)control=`<div class="switch-row"><span>${yb?'556 nm cooling':'Further cooling light'}</span>${switchButton('cooling','Further cooling light',state.cooling)}</div><p class="help">${state.cooling?'The smaller cloud illustrates reduced random motion, not a measured temperature.':'The more spread-out dots illustrate larger motion. Holding an atom and cooling it are different tasks.'}</p>`;
 if(s===4)control=`<div class="inline-controls"><button class="chip ${state.route==='reservoir'?'selected':''}" data-route="reservoir" aria-pressed="${state.route==='reservoir'}">Via a reservoir</button><button class="chip ${state.route==='direct'?'selected':''}" data-route="direct" aria-pressed="${state.route==='direct'}">Direct to tweezers</button></div><p class="help">Switch between two valid layouts. This explorer combines common ideas, not MatriQ’s proprietary apparatus.</p>`;
 if(s===5)control=`<div class="inline-controls"><button class="button small" id="lose-atom" ${!state.atoms.some(Boolean)?'disabled':''}>Remove an atom</button><button class="button primary small" id="arrange" ${state.atoms.every(Boolean)||state.reserve===0?'disabled':''}>Fill the gaps ↗</button><button class="button small" id="reload">New batch</button></div><p class="help" id="supply-message" role="status">${state.supplyMessage} ${state.reserve} spare atoms remain ${state.route==='reservoir'?'in this toy reservoir':'in surplus traps'}.</p>`;
 return `<div class="lab-grid">${scene(supplyDiagram(),'ATOM SUPPLY / APPARATUS OVERVIEW')}${explain(`STEP 0${s+1} / 06`,t[0],t[1],`<strong>${t[2]}</strong>${t[3]}`,t[4])}</div><div class="stepper" aria-label="Atom supply steps">${['Source','Slow','Capture','Cool','Store','Arrange'].map((x,i)=>`<button class="stage-step ${i===s?'active':i<s?'done':''}" data-stage="${i}" ${i===s?'aria-current="step"':''}><b>0${i+1}</b>${x}</button>`).join('')}</div><div class="transport"><span class="count">STEP ${s+1} OF 6</span><div class="transport-actions"><button class="button ghost" id="autoplay" aria-pressed="${!!timer}">${timer?'Ⅱ Pause':'▷ Play journey'}</button><button class="button" id="prev-stage" ${s===0?'disabled':''} aria-label="Previous supply step">←</button><button class="button primary" id="next-stage">${s===5?'Single-qubit control ↗':'Next step →'}</button></div></div><div class="controls-row"><section class="control-card"><h3 class="micro-title">TAKE THE CONTROLS <span class="muted">TRY IT YOURSELF</span></h3>${control}</section><section class="control-card"><h3 class="micro-title">SPECIES NOTE <span class="muted">${sp.isotope}</span></h3><div class="control-label">${s<=1?sp.source:s<4?sp.cool:sp.encoding}</div><p class="help">${s<=1?'The vacuum architecture may share design principles, but source temperatures, optics, and atomic transitions are species-specific. Sources must be designed for the selected species.':s<4?'The wavelengths here are representative cooling transitions. Trap wavelengths and gate wavelengths are chosen separately.':'Only after selecting and initializing two internal states do we have a computational qubit. A filled array alone is not an initialized processor.'}</p><a class="source-ref" href="#sources">Explore the sources ↗</a></section></div>`;
}
function bloch(){const q=qubit(state.theta,state.phi),cx=285,cy=152,r=104;const proj=(x,y,z)=>[cx+r*(x+.35*y),cy+r*(.3*y-z)];const p=proj(q.x,q.y,q.z);let v=svgStart('Bloch sphere: an arrow shows the qubit state. North is zero, south is one. The equator has equal Z probabilities but different phases.');
 v+=`<circle cx="${cx}" cy="${cy}" r="${r}" fill="#15212b" stroke="#567189"/><ellipse cx="${cx}" cy="${cy}" rx="${r}" ry="32" fill="none" stroke="#4e677d"/><ellipse cx="${cx}" cy="${cy}" rx="36" ry="${r}" fill="none" stroke="#3a5164"/>${line(cx-130,cy,cx+130,cy,'#445a6c','stroke-dasharray="3 5"')}${line(cx,cy-130,cx,cy+130,'#5a778f')}${line(cx-45,cy-39,cx+45,cy+39,'#384c5d')}${line(cx,cy,p[0],p[1],'#b8d4ec','stroke-width="2.5"')}${circle(p[0],p[1],6,'#bcd8f0')}${circle(p[0],p[1],14,'none','stroke="#a0c4e345"')}${circle(cx,cy,3,'#7394b0')}`;
 v+=text(cx,22,'|0⟩','#bbd1e3',13,'text-anchor="middle"')+text(cx,299,'|1⟩','#bbd1e3',13,'text-anchor="middle"')+text(cx+140,cy+4,'+X','#87a1b8',10)+text(cx+46,cy+49,'+Y','#63829d',10);
 v+=text(510,88,'TWO INTERNAL STATES','#718ea6',9,'letter-spacing="1.4"')+line(510,133,713,133,'#83a5c2','stroke-width="2"')+line(510,223,713,223,'#88adcc','stroke-width="2"')+text(725,137,'|1⟩','#b7c6d2',12)+text(725,227,'|0⟩','#b7c6d2',12);
 v+=`<path d="M606 211v-64" fill="none" stroke="#b5c2f0" stroke-width="2" marker-end="url(#arrow)"/>`+text(619,183,'coherent drive','#abc0d2',9)+text(510,270,state.species==='Rb'?'Hyperfine pair · schematic':'Nuclear-spin pair · schematic','#6e8ba4',9)+text(510,286,'Splitting and geometry are illustrative','#4f697f',8);
 return v+'</svg>';
}
function control(){const q=qubit(state.theta,state.phi),sp=species[state.species];return `<div class="lab-grid">${scene(bloch()+`<div class="state-display">|ψ⟩ = cos(θ/2)|0⟩ + e<sup>iφ</sup> sin(θ/2)|1⟩</div>`,'COHERENT CONTROL / STATE SPACE','Bloch sphere · projected view')}${explain('THE KEY IDEA','Control the internal state.',`${sp.detail} A calibrated coherent drive changes the amplitudes and relative phase.`,`<strong>What the arrow means</strong>North is |0⟩, south is |1⟩. Points around the equator have the same 50/50 Z outcomes, but can interfere differently.`,['One carrier','Two-state system'])}</div><div class="controls-row"><section class="control-card"><h3 class="micro-title">BUILD A STATE <span class="muted">IDEAL Ry(θ), THEN PHASE φ</span></h3><label class="control-label" for="theta">Pulse rotation θ<output id="theta-value">${state.theta}°</output></label><input class="range" id="theta" type="range" min="0" max="180" step="1" value="${state.theta}"><div class="range-ends"><span>0 · |0⟩</span><span>90 · equal superposition</span><span>180 · |1⟩</span></div><label class="control-label" for="phi" style="margin-top:24px">Relative phase φ<output id="phi-value">${state.phi}°</output></label><input class="range" id="phi" type="range" min="0" max="360" step="1" value="${state.phi}"><div class="range-ends"><span>0°</span><span>180°</span><span>360°</span></div><div class="inline-controls" style="margin-top:20px">${[['zero','|0⟩'],['one','|1⟩'],['plus','|+⟩'],['minus','|−⟩']].map(([k,v])=>`<button class="chip" data-preset="${k}">Prepare ${v}</button>`).join('')}</div><p class="help">Presets prepare a fresh state. θ is a calibrated pulse area, not the laser’s optical frequency.</p></section><section class="control-card"><h3 class="micro-title">IF YOU MEASURE IN Z <span class="muted">BORN PROBABILITIES</span></h3><div class="prob-bars"><div class="prob-item"><label><span>|0⟩</span><b id="prob-zero">${pct(q.p0)}</b></label><div class="prob-bar"><span id="bar-zero" style="width:${pct(q.p0)}"></span></div></div><div class="prob-item"><label><span>|1⟩</span><b id="prob-one">${pct(q.p1)}</b></label><div class="prob-bar"><span id="bar-one" style="width:${pct(q.p1)}"></span></div></div></div><p class="experiment-note">Try |+⟩ and |−⟩. Their Z probabilities match. The phase difference becomes visible if you measure in X.</p><p class="help">${sp.drive} A gate instruction specifies pulse duration, strength, phase, and detuning.</p><a class="source-ref" href="#sources">Encoding and control references ↗</a></section></div>${next('readout','Send this state to the measurement experiment →',true)}${next('gates','Or let two atoms interact →')}`;}
const gateSteps=[['Ready','Two atoms store information in qubit states. A selected component couples to a Rydberg level.'],['Excite the control','A π pulse promotes the coupled control component to |r⟩. The Rydberg level is used during the gate.'],['Drive the target','A target 2π pulse would cycle its coupled component up and back. With a nearby Rydberg control, the double excitation is shifted out of resonance.'],['Return the control','A final π pulse brings the control back. The different paths accumulate different phases. With calibrated phase corrections this realizes an entangling controlled-phase gate.']];
function gateDiagram(){const near=interactionRatio(state.distance)>1,step=state.gateStep;const x1=265,x2=265+state.distance*28;let v=svgStart('Two atoms with tunable separation. In the blockade picture a Rydberg excitation shifts simultaneous excitation out of resonance.');
 const ryd=step===1||step===2;v+=line(140,232,700,232,'#3b5164','stroke-dasharray="3 7"');
 if(ryd)v+=circle(x1,153,93,'url(#coldGlow)')+circle(x1,153,75,'none','stroke="#c0b3ec" stroke-dasharray="4 5"')+text(x1,52,'CONTROL IN |r⟩','#bcafe1',9,'text-anchor="middle"');
 v+=circle(x1,153,24,'#192b3b','stroke="#7793ab"')+circle(x1,153,6,ryd?'#c1b1e9':'#b5d3ec')+circle(x2,153,24,'#192b3b','stroke="#7793ab"')+circle(x2,153,6,step===2&&!near?'#c1b1e9':'#b5d3ec');
 if(step===2){v+=`<path d="M${x2} 75v45" stroke="#91bce0" stroke-width="3" marker-end="url(#arrow)"/>`;v+=text(x2,63,near?'SECOND EXCITATION SUPPRESSED':'WEAK INTERACTION','#a6c8d0',8,'text-anchor="middle"');if(near)v+=`<path d="M${x1+40} 153q${(x2-x1-80)/2} -55 ${x2-x1-80} 0" fill="none" stroke="#b9a7da" stroke-width="1.5" stroke-dasharray="4 4"/>`;}
 v+=text(x1,206,'A · CONTROL','#acbdcc',11,'text-anchor="middle"')+text(x2,206,'B · TARGET','#acbdcc',11,'text-anchor="middle"')+line(x1,254,x2,254,'#5b7992')+text((x1+x2)/2,274,`${state.distance.toFixed(1)} μm`,'#a7c0d6',11,'text-anchor="middle"')+text(400,311,'SELECTED COUPLED BRANCH · NOT A FULL WAVEFUNCTION','#61809b',8,'text-anchor="middle" letter-spacing="1"');return v+'</svg>';
}
function gates(){const ratio=interactionRatio(state.distance),near=ratio>1;let experiment;
 if(state.gateMode==='blockade')experiment=`<div class="lab-grid">${scene(gateDiagram(),'RYDBERG BLOCKADE / BRANCH PICTURE')}${explain(`PULSE ${state.gateStep} / 3`,gateSteps[state.gateStep][0],gateSteps[state.gateStep][1],`<strong>${near?'Interaction dominates':'Drive dominates'}</strong>${near?'In this illustrative model the shift exceeds the drive scale. Larger ratios increase suppression of double excitation.':'The shift is smaller than the chosen drive scale. The blockade assumption weakens; the ideal gate is no longer assured.'}`,['Temporary |r⟩','Conditional phase'])}</div><div class="transport"><span class="count">TEACHING SEQUENCE · π → 2π → π</span><div class="transport-actions"><button class="button" id="gate-reset">Reset</button><button class="button primary" id="gate-next" ${state.gateStep===3?'disabled':''}>Next pulse →</button></div></div><div class="controls-row"><section class="control-card"><h3 class="micro-title">TUNE THE SEPARATION <span class="muted">ILLUSTRATIVE INTERACTION</span></h3><label class="control-label" for="distance">Atom spacing<output>${state.distance.toFixed(1)} μm</output></label><input id="distance" class="range" type="range" min="3" max="12" step=".1" value="${state.distance}"><div class="range-ends"><span>3 μm · stronger</span><span>12 μm · weaker</span></div><p class="help">Toy van der Waals model: |V|/(ℏΩ) = (6 μm / r)⁶ = <b>${ratio.toFixed(2)}</b>. The chosen 6 μm reference is not a MatriQ specification or a universal blockade radius. Real interactions depend on species, Rydberg state, geometry, fields, and drive.</p></section><section class="control-card"><h3 class="micro-title">WHY THIS CAN ENTANGLE</h3><p class="help">The interaction changes the phase of joint-state paths. For suitable superposition inputs, this conditional phase creates entanglement.</p><div class="experiment-note">The picture follows one coupled branch. Experimental pulse sequences may be shaped or simultaneous; phases require calibration. It does not calculate gate fidelity.</div><a class="source-ref" href="#sources">Rb and Yb gate demonstrations ↗</a></section></div>`;
 else{const isCZ=state.gateMode==='cz';experiment=`<div class="lab-grid">${scene(logicDiagram(isCZ),'GATE LOGIC / IDEAL UNITARY','Ideal gate · independent of spacing control')}${explain('FROM PHYSICS TO LOGIC',isCZ?'CZ changes a phase.':'CNOT flips a target.',isCZ?'CZ leaves |00⟩, |01⟩, and |10⟩ unchanged and multiplies |11⟩ by −1. This is a relative phase, not a bit flip.':'For basis-state inputs, CNOT flips B when A is 1. Physically, the target changes between its chosen internal qubit states.',`<strong>Connect the gates</strong>CNOT = (I ⊗ H) · CZ · (I ⊗ H). The target Hadamards convert a conditional phase into a conditional flip.`,['A joint operation','Ideal circuit'])}</div><div class="controls-row"><section class="control-card"><h3 class="micro-title">${isCZ?'PHASE BECOMES VISIBLE IN INTERFERENCE':'CHOOSE A BASIS-STATE INPUT'}</h3>${isCZ?`<p class="help">Input |++⟩ has four equal amplitudes. Apply CZ: the |11⟩ amplitude becomes negative. All four Z outcomes remain 25%.</p><div class="experiment-note">Equal probabilities do not mean the same state. The CZ output is entangled; the input |++⟩ is separable.</div>`:`<div class="inline-controls">${[0,1].map(x=>`<button class="chip ${state.inputA===x?'selected':''}" data-input-a="${x}" aria-pressed="${state.inputA===x}">A = ${x}</button>`).join('')}<span style="width:12px"></span>${[0,1].map(x=>`<button class="chip ${state.inputB===x?'selected':''}" data-input-b="${x}" aria-pressed="${state.inputB===x}">B = ${x}</button>`).join('')}</div><p class="help">Input |${state.inputA}${state.inputB}⟩ → output |${cnot(state.inputA,state.inputB).join('')}⟩. The atoms stay in their traps.</p>`}</section><section class="control-card"><h3 class="micro-title">THE COMPLETE BASIS MAPPING</h3><div class="table-wrap"><table><thead><tr><th>INPUT</th><th>${isCZ?'CZ OUTPUT':'CNOT OUTPUT'}</th><th>CHANGE</th></tr></thead><tbody>${[0,1,2,3].map(i=>{const a=i>>1,b=i%2;return `<tr class="${!isCZ&&a===state.inputA&&b===state.inputB?'highlight':''}"><td>|${a}${b}⟩</td><td>${isCZ?(i===3?'−':'')+`|${a}${b}⟩`:`|${cnot(a,b).join('')}⟩`}</td><td>${isCZ?(i===3?'Phase sign':'None'):(a?'B flips':'None')}</td></tr>`;}).join('')}</tbody></table></div></section></div>`;}
 return `<div class="chapter-tabs" role="group" aria-label="Gate experiment">${[['blockade','1. The physical interaction'],['cz','2. CZ phase'],['cnot','3. CNOT flip']].map(([k,v])=>`<button class="button" data-gate-mode="${k}" aria-pressed="${state.gateMode===k}">${v}</button>`).join('')}</div>${experiment}${next('readout','Read out the result →')}`;
}
function logicDiagram(isCZ){let v=svgStart(isCZ?'CZ acts on the plus plus state, changing the sign of the eleven amplitude while keeping all four Z probabilities equal.':'CNOT basis state mapping: control A stays the same and target B flips if A is one.');if(isCZ){const vals=czAmplitudes(true);v+=text(400,47,'|++⟩ → CZ → (|00⟩ + |01⟩ + |10⟩ − |11⟩) / 2','#adc4d8',17,'text-anchor="middle"');v+=line(135,160,665,160,'#4b6377');vals.forEach((a,i)=>{const x=175+i*150;v+=`<rect x="${x-27}" y="${a>0?90:160}" width="54" height="70" rx="3" fill="${a>0?'#aac6de':'#bcace8'}" opacity=".8"/>`+text(x,a>0?79:247,a>0?'+½':'−½',a>0?'#b1c8dc':'#c7b8e8',14,'text-anchor="middle"')+text(x,279,`|${i.toString(2).padStart(2,'0')}⟩`,'#acc0d1',13,'text-anchor="middle"');});v+=text(400,307,'SIGNED AMPLITUDES · Z PROBABILITY = ¼ FOR EACH','#5d7b94',8,'text-anchor="middle" letter-spacing="1.3"');}
 else{const a=state.inputA,b=state.inputB,out=cnot(a,b);v+=line(170,110,635,110,'#5a7891','stroke-width="2"')+line(170,219,635,219,'#5a7891','stroke-width="2"')+line(400,110,400,219,'#b8cfe3','stroke-width="2"')+circle(400,110,7,'#bad3e9')+circle(400,219,22,'#11202d','stroke="#bad3e9" stroke-width="2"')+line(378,219,422,219,'#bad3e9','stroke-width="2"')+line(400,197,400,241,'#bad3e9','stroke-width="2"');v+=text(120,115,`A = ${a}`,'#b2c7d9',15)+text(120,224,`B = ${b}`,'#b2c7d9',15)+text(660,115,`${out[0]}`,'#b7d2e9',24)+text(660,226,`${out[1]}`,'#b7d2e9',24)+text(400,54,'CNOT = H ON B → CZ → H ON B','#809ab0',10,'text-anchor="middle" letter-spacing="1"')+text(400,291,a?'CONTROL IS 1 · TARGET CHANGES INTERNAL STATE':'CONTROL IS 0 · TARGET STAYS THE SAME','#91aac0',10,'text-anchor="middle"');}return v+'</svg>';}
function preparation(){return state.measurePrep==='current'?{theta:state.theta,phi:state.phi}:({zero:{theta:0,phi:0},one:{theta:180,phi:0},plus:{theta:90,phi:0},minus:{theta:90,phi:180}})[state.measurePrep];}
function measurementDiagram(){const total=state.counts.zero+state.counts.one,p=preparation(),p1=basisProbability(p.theta,p.phi,state.basis);let v=svgStart('Measurement histogram with zero and one outcomes. Every shot prepares a fresh atom state before measurement.');
 v+=text(165,49,'PREPARE','#88a0b4',9,'text-anchor="middle" letter-spacing="1.5"')+text(400,49,`${state.basis} BASIS`,'#88a0b4',9,'text-anchor="middle" letter-spacing="1.5"')+text(650,49,'COUNT','#88a0b4',9,'text-anchor="middle" letter-spacing="1.5"');v+=circle(165,149,53,'url(#coldGlow)')+circle(165,149,21,'#213547','stroke="#84a3bd"')+circle(165,149,5,'#b4cfe7');v+=`<path d="M234 149h80m121 0h80" stroke="#526c82" marker-end="url(#arrow)"/>`;
 v+=`<rect x="330" y="105" width="100" height="90" rx="7" fill="#1d2c39" stroke="#4a6277"/>${text(380,143,'BASIS','#7490a8',9,'text-anchor="middle"')}${text(380,172,state.basis,'#b7d2e9',23,'text-anchor="middle"')}`;
 v+=line(550,234,752,234,'#59768e');[state.counts.zero,state.counts.one].forEach((n,i)=>{const x=583+i*102,h=total?n/total*130:3;v+=`<rect x="${x-27}" y="${234-h}" width="54" height="${h}" rx="3" fill="${i?'#7ca4c7':'#a0c0dc'}" opacity=".85"/>`+text(x,220-h,`${n}`,'#b2c8da',14,'text-anchor="middle"')+text(x,258,`${i}`,'#8ca8c0',12,'text-anchor="middle"');});v+=text(165,237,state.measurePrep==='current'?'State from chapter 02':({zero:'|0⟩',one:'|1⟩',plus:'|+⟩',minus:'|−⟩'})[state.measurePrep],'#adc8df',15,'text-anchor="middle"')+text(380,265,'Rotate basis → detect','#6d8ba4',9,'text-anchor="middle"')+text(650,293,total?`${total} SHOTS · P(1) EXPECTED ${pct(p1)}`:'NO SHOTS YET','#6d8ba4',9,'text-anchor="middle"');return v+'</svg>';}
function readout(){const prep=preparation(),p1=basisProbability(prep.theta,prep.phi,state.basis),total=state.counts.zero+state.counts.one;return `<div class="lab-grid">${scene(measurementDiagram(),'MEASUREMENT / REPEATED PREPARATION','Ideal projective model · no detector noise')}${explain('THE KEY IDEA','Read out a qubit.','A measurement returns a classical bit in the chosen basis. Repeat state preparation and measurement to estimate the probabilities.',`<strong>How light becomes data</strong>Use a state-dependent optical signal, collect photons, and classify the result. ${species[state.species].read}`,['Basis matters','Photon detection'])}</div><div class="controls-row"><section class="control-card"><h3 class="micro-title">RUN THE EXPERIMENT <span class="muted">FRESH STATE EACH SHOT</span></h3><label class="control-label" for="measure-prep">Prepared state<select id="measure-prep">${[['plus','|+⟩'],['minus','|−⟩'],['zero','|0⟩'],['one','|1⟩'],['current','From single-qubit controls']].map(([k,v])=>`<option value="${k}" ${state.measurePrep===k?'selected':''}>${v}</option>`).join('')}</select></label><div class="control-label">Measurement basis<div class="inline-controls">${['Z','X'].map(b=>`<button class="chip ${state.basis===b?'selected':''}" data-basis="${b}" aria-pressed="${state.basis===b}">${b}</button>`).join('')}</div></div><div class="inline-controls"><button id="one-shot" class="button">Measure once</button><button id="many-shots" class="button primary">Run 200 shots ↗</button><button id="clear-shots" class="button">Clear</button></div><p class="help" role="status">${state.last!==null?`Last outcome: ${state.last}. `:''}${total} shots in this configuration. Changing state or basis clears the counts.</p></section><section class="control-card"><h3 class="micro-title">EXPECTED OUTCOMES</h3><div class="metric-pair"><div><strong>${pct(1-p1)}</strong><small>Expected outcome 0</small></div><div><strong>${pct(p1)}</strong><small>Expected outcome 1</small></div></div><p class="help">X measurement distinguishes |+⟩ from |−⟩. Z measurement cannot: both give 50/50. In hardware, an X-basis measurement can be implemented by rotating the state before readout.</p><div class="experiment-note">This model counts ideal outcomes, not camera brightness. A dark signal can indicate a qubit state, an empty trap, or detection failure, depending on the readout scheme.</div></section></div><details><summary>Why not keep measuring the same superposition?</summary>After an ideal projective measurement, the state is conditioned on the outcome. Measuring again in the same basis gives the same outcome unless something changes. The 200-shot button re-prepares the original state each time.</details>${next('logical','What if the qubit makes an error? →')}`;}
function logicalDiagram(){let v=svgStart('Three physical carriers encode a repetition code. Toggle bit-flip errors, inspect two parity checks, and apply a syndrome-based correction.');const xs=[220,400,580];v+=text(400,32,`α|${state.logicalBits.join('')}⟩ + β|${state.logicalBits.map(b=>b^1).join('')}⟩`,'#aec7dd',18,'text-anchor="middle"');xs.forEach((x,i)=>{const err=state.logicalBits[i];v+=circle(x,124,31,'#1c2f40',`stroke="${err?'#dbac84':'#7a9ab5'}" stroke-width="1.5"`)+circle(x,124,7,err?'#dca67e':'#b3d0e8')+text(x,182,`Q${i+1}`,'#95afc5',11,'text-anchor="middle"')+text(x,212,err?'X ERROR':'NO X ERROR',err?'#d2a47c':'#61809b',9,'text-anchor="middle"');});
 v+=`<path d="M220 161v94h180v-94M400 161v94h180v-94" fill="none" stroke="#4d667b"/>`;const syn=[state.logicalBits[0]^state.logicalBits[1],state.logicalBits[1]^state.logicalBits[2]];syn.forEach((n,i)=>{const x=310+i*180;v+=`<rect x="${x-48}" y="239" width="96" height="33" rx="5" fill="#213547" stroke="#4f6a81"/>`+text(x,260,`PARITY ${i+1}: ${n}`,'#acc6dd',10,'text-anchor="middle"');});v+=text(400,305,'ERROR FLAGS ARE VISUAL AIDS · CHECKS REVEAL PARITY, NOT α OR β','#5e7c95',8,'text-anchor="middle" letter-spacing=".5"');return v+'</svg>';}
function logical(){const r=surfaceResources(state.distanceCode),errors=state.logicalBits.reduce((a,b)=>a+b,0);return `<div class="lab-grid">${scene(logicalDiagram(),'ERROR CHECKS / THREE-QUBIT TOY CODE','Bit flips only · not full quantum protection')}${explain('THE KEY IDEA','Encode a logical qubit.','A physical qubit is one carrier and its two chosen states. A logical qubit is information encoded across a group, with checks and decoding to identify errors.',`<strong>No copying required</strong>Encoding α|0⟩ + β|1⟩ gives α|000⟩ + β|111⟩ here. Individual atoms do not each hold a separate copy of the unknown state.`,['Encoded information','Syndrome + decoder'])}</div><div class="controls-row"><section class="control-card"><h3 class="micro-title">INJECT A BIT-FLIP ERROR <span class="muted">TOY REPETITION CODE</span></h3><div class="inline-controls">${[0,1,2].map(i=>`<button class="chip ${state.logicalBits[i]?'selected':''}" data-error="${i}" aria-pressed="${!!state.logicalBits[i]}">Q${i+1} ${state.logicalBits[i]?'· X error':'· no error'}</button>`).join('')}</div><div class="inline-controls" style="margin-top:17px"><button id="correct" class="button primary">Read checks & correct ↗</button><button id="reset-errors" class="button">Reset</button></div><div class="experiment-note" id="correction-message" role="status">${state.correctionResult||'Try one X error, then correct it. Next try two errors and see the limit.'}</div><p class="help">This code corrects one bit flip under ideal checks. It does not protect against arbitrary phase errors. The visual flags let you see the actual errors; the decoder only uses the two parity checks.</p></section><section class="control-card"><h3 class="micro-title">WHAT DOES “OVERHEAD” MEAN? <span class="muted">EXAMPLE RESOURCE COUNT</span></h3><label class="control-label" for="code-distance">Rotated surface-code distance<select id="code-distance">${[3,5,7,9].map(d=>`<option value="${d}" ${d===state.distanceCode?'selected':''}>d = ${d}</option>`).join('')}</select></label><div class="metric-pair"><div><strong>${r.data}</strong><small>Data qubits · d²</small></div><div><strong>${r.ancilla}</strong><small>Check ancillas · d² − 1</small></div><div><strong>${r.total}</strong><small>Physical per patch</small></div></div><p class="help">One illustrative patch encodes one logical qubit. Under ideal checks, distance ${state.distanceCode} can correct up to ${r.correctable} arbitrary single-qubit error${r.correctable===1?'':'s'}. Repeated noisy checks, routing, spare atoms, and gates add resources and time.</p><p class="help">There is no universal physical-to-logical conversion ratio. Code, physical error rates, circuit depth, and target reliability determine the actual budget.</p></section></div><div class="note-block"><strong>Requirements for fault tolerance.</strong> Quantum error correction requires bit- and phase-error checks, repeated syndrome extraction, a decoder, and physical error rates low enough for the chosen code and protocol. Increasing an array’s size alone does not provide error correction.</div>${next('sources','Explore the papers and model notes →')}`;}
function referencePage(){return `<div class="source-card"><h3>Scope and assumptions</h3><p>This explorer uses public neutral-atom experiments to explain components and operations. It makes no claim about MatriQ’s actual species choice, layout, pulse sequence, performance, or roadmap. Rb and Yb require species-specific sources, cooling transitions, and control optics.</p><p>Dots, distances, phase diagrams, and pulse steps are conceptual. The single-qubit and measurement panels use ideal two-level mathematics; they omit noise, leakage, drift, finite temperature, and detector error. The blockade ratio is a normalized r⁻⁶ example, not a fitted device model. Resource counts apply to the named example code layout.</p><p>No external scripts, analytics, or live laboratory connections. Learning controls stay in this browser session; no account details are collected by the explorer.</p></div><div class="source-list">${sources.map(s=>`<article class="source-card"><p class="eyebrow">${s.n} / ${s.author}</p><h3>${s.title}</h3><p>${s.text}</p><a href="${s.url}" target="_blank" rel="noopener noreferrer">Read the primary source ↗</a></article>`).join('')}</div><div class="note-block">Sources checked 16 October 2026. The references cover selected neutral-atom implementations.</div>${next('supply','Return to the atom journey →')}`;}

function render(){const chapter=state.chapter;document.querySelectorAll('[data-chapter]').forEach(a=>{a.classList.toggle('active',a.dataset.chapter===chapter);if(a.dataset.chapter===chapter)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.querySelectorAll('[data-species]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.species===state.species));const h=headings[chapter];$('#workspace').innerHTML=`<section aria-labelledby="chapter-title"><div class="chapter-heading"><div><p class="eyebrow">${h[0]}</p><h2 id="chapter-title">${h[1]}</h2></div><div class="chapter-hint">${h[2]}</div></div>${({supply,control,gates,readout,logical,sources:referencePage})[chapter]()}</section>`;bind();}
function on(id,event,fn){const el=$('#'+id);if(el)el.addEventListener(event,fn);}
function rerenderPreserve(id){render();const el=$('#'+id);if(el)el.focus({preventScroll:true});}
function resetCounts(){state.counts={zero:0,one:0};state.last=null;}
function stopJourney(){if(timer){clearInterval(timer);timer=null;}}
function bind(){document.querySelectorAll('[data-carry-state]').forEach(a=>a.addEventListener('click',()=>{state.measurePrep='current';resetCounts();}));document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{stopJourney();state.stage=Number(b.dataset.stage);render();});on('prev-stage','click',()=>{stopJourney();state.stage=Math.max(0,state.stage-1);render();});on('next-stage','click',()=>{stopJourney();if(state.stage===5)location.hash='control';else{state.stage++;render();}});on('autoplay','click',()=>{if(timer){stopJourney();render();return;}if(state.stage===5)state.stage=0;timer=setInterval(()=>{state.stage++;if(state.stage>=5)stopJourney();render();},4000);render();});on('flux','input',e=>{state.flux=Number(e.target.value);refreshSupplyScene();const out=$('#flux').previousElementSibling.querySelector('output');out.textContent=['','Low','Medium','High'][state.flux];});for(const k of ['slower','gradient','cooling'])on(k,'click',()=>{state[k]=!state[k];rerenderPreserve(k);});document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{state.route=b.dataset.route;render();});on('lose-atom','click',()=>{const i=state.atoms.findLastIndex(Boolean);if(i>=0)state.atoms[i]=false;state.supplyMessage='An atom was lost. The information on that carrier is not recovered by refilling.';render();});on('arrange','click',()=>{const r=arrange(state.atoms,state.reserve);state.atoms=r.atoms;state.reserve=r.reservoir;state.supplyMessage=`Moved ${r.moved} fresh atom${r.moved===1?'':'s'} into empty traps. ${state.atoms.filter(Boolean).length} of 16 sites occupied.`;render();});on('reload','click',()=>{state.atoms=[1,0,1,1,0,1,1,0,1,1,0,1,0,1,1,1].map(Boolean);state.reserve=8;state.supplyMessage='New illustrative loading cycle: 11 of 16 sites occupied.';render();});
 for(const k of ['theta','phi'])on(k,'input',e=>{state[k]=Number(e.target.value);resetCounts();refreshQubit();});document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{const [theta,phi]=({zero:[0,0],one:[180,0],plus:[90,0],minus:[90,180]})[b.dataset.preset];state.theta=theta;state.phi=phi;resetCounts();render();});
 document.querySelectorAll('[data-gate-mode]').forEach(b=>b.onclick=()=>{state.gateMode=b.dataset.gateMode;render();});on('gate-next','click',()=>{state.gateStep=Math.min(3,state.gateStep+1);render();});on('gate-reset','click',()=>{state.gateStep=0;render();});on('distance','input',e=>{state.distance=Number(e.target.value);const card=$('#distance').closest('.control-card');card.querySelector('output').textContent=state.distance.toFixed(1)+' μm';card.querySelector('.help b').textContent=interactionRatio(state.distance).toFixed(2);refreshGateScene();});
 for(const axis of ['a','b'])document.querySelectorAll(`[data-input-${axis}]`).forEach(b=>b.onclick=()=>{state[axis==='a'?'inputA':'inputB']=Number(b.dataset[axis==='a'?'inputA':'inputB']);render();});on('measure-prep','change',e=>{state.measurePrep=e.target.value;resetCounts();render();});document.querySelectorAll('[data-basis]').forEach(b=>b.onclick=()=>{state.basis=b.dataset.basis;resetCounts();render();});for(const [id,n]of [['one-shot',1],['many-shots',200]])on(id,'click',()=>{const p=preparation(),prob=basisProbability(p.theta,p.phi,state.basis);const r=shots(prob,n);state.counts.zero+=r.zero;state.counts.one+=r.one;state.last=n===1?(r.one?1:0):null;render();});on('clear-shots','click',()=>{resetCounts();render();});
 document.querySelectorAll('[data-error]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.error);state.logicalBits[i]^=1;state.correctionResult=null;render();});on('reset-errors','click',()=>{state.logicalBits=[0,0,0];state.correctionResult=null;render();});on('correct','click',()=>{const r=correction(state.logicalBits);const syndrome=r.syndrome.join('');state.logicalBits=r.corrected;const residual=r.corrected.some(Boolean);state.correctionResult=`Syndrome ${syndrome}. ${r.index===undefined?'No correction indicated.':`Decoder flips Q${r.index+1}.`} ${residual?'An uncorrected logical X remains: the pattern exceeds this code’s one-bit-flip guarantee.':'The encoded state is restored in this ideal bit-flip model.'}`;render();});on('code-distance','change',e=>{state.distanceCode=Number(e.target.value);render();});}
function refreshSupplyScene(){$('.scene .diagram').outerHTML=supplyDiagram();}
function refreshQubit(){const q=qubit(state.theta,state.phi);$('.scene .diagram').outerHTML=bloch();$('#theta-value').textContent=state.theta+'°';$('#phi-value').textContent=state.phi+'°';$('#prob-zero').textContent=pct(q.p0);$('#prob-one').textContent=pct(q.p1);$('#bar-zero').style.width=pct(q.p0);$('#bar-one').style.width=pct(q.p1);}
function refreshGateScene(){$('.scene .diagram').outerHTML=gateDiagram();const near=interactionRatio(state.distance)>1;const callout=$('.explain-card .callout');callout.innerHTML=`<strong>${near?'Interaction dominates':'Drive dominates'}</strong>${near?'In this illustrative model the shift exceeds the drive scale. Larger ratios increase suppression of double excitation.':'The shift is smaller than the chosen drive scale. The blockade assumption weakens; the ideal gate is no longer assured.'}`;}
function route(){const key=location.hash.slice(1);state.chapter=Object.hasOwn(headings,key)?key:'supply';if(state.chapter!=='supply')stopJourney();render();window.scrollTo?.(0,0);}
window.addEventListener('hashchange',route);
document.querySelectorAll('[data-species]').forEach(b=>b.onclick=()=>{state.species=b.dataset.species;render();});
function renderGlossary(){const q=$('#glossary-search').value.toLowerCase().trim(),items=glossary.filter(([k,v])=>(k+' '+v).toLowerCase().includes(q));$('#glossary-items').innerHTML=items.length?items.map(([k,v])=>`<article class="glossary-entry"><h3>${k}</h3><p>${v}</p></article>`).join(''):'<p class="help">No matching term. Try “spin”, “trap”, or “phase”.</p>';}
const openGlossary=()=>{$('#glossary').showModal();renderGlossary();$('#glossary-search').focus();};$('#glossary-open').onclick=openGlossary;$('#glossary-open-mobile').onclick=openGlossary;$('#glossary-close').onclick=()=>$('#glossary').close();$('#glossary-search').oninput=renderGlossary;$('#glossary').addEventListener('click',e=>{if(e.target===$('#glossary')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
route();
